/**
 * Secrets (`wrangler secret put`) plus optional overrides.
 * Bindings/vars are generated by `npm run cf-typegen`.
 */
interface Env {
  IDEMPOTENCY: KVNamespace;
  FISKL_API_KEY: string;
  WISE_API_TOKEN?: string;
  FISKL_API_BASE: string;
  FISKL_COMPANY_ID: string;
  FISKL_DEFAULT_EXPENSE_ACCOUNT_ID: string;
  FISKL_DEFAULT_INCOME_ACCOUNT_ID: string;
  FISKL_CONVERSION_COUNTERPARTY_ACCOUNT_ID?: string;
  WISE_PERSONAL_PROFILE_ID: string;
  WISE_BUSINESS_PROFILE_ID: string;
  WISE_ENVIRONMENT: string;
  WISE_REQUIRE_SIGNATURE?: string;
  WISE_PROFILE_TO_FISKL_ACCOUNT: string;
}
